using System.Data;using System.Text;using Dapper;using Microsoft.Data.SqlClient;using Microsoft.Extensions.Configuration;using GraphApi.Models.VTS.TipoIdentificacion;namespace GraphApi.Services.VTS.TipoIdentificacion{    public class TipoIdentificacionService : ITipoIdentificacionService    {        private readonly IDbConnection   _objDbDefault;        private readonly IConfiguration  _objConfig;        public TipoIdentificacionService(IDbConnection objDbDefault, IConfiguration objConfig)        {            _objDbDefault = objDbDefault;            _objConfig    = objConfig;        }        public async Task<IEnumerable<clReadTipoIdentificacion>> GetTipoIdentificacions(            int userId,            string windowName)        {            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT  *                 FROM vts.TipoIdentificacion (NOLOCK)            ");            var vParameters = new DynamicParameters();            var vList = await _objDbDefault.QueryAsync<clReadTipoIdentificacion>(vSql.ToString(), vParameters);            return vList;        }        public async Task<IEnumerable<dynamic>> GetTipoIdentificacionsDynamic(            int? tipoIdentificacionID,            string? tipoIdentificacion,            bool? bEliminado,            string? columnNames,            int userId,            string windowName)        {            string sColumnNames = string.IsNullOrWhiteSpace(columnNames) ? "TipoIdentificacionID, TipoIdentificacion, bEliminado" : columnNames;            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT {sColumnNames}                FROM vts.TipoIdentificacion (NOLOCK)                WHERE 1=1            ");            var vParameters = new DynamicParameters();            if (tipoIdentificacionID.HasValue)            {                vSql.Append(" AND TipoIdentificacionID = @TipoIdentificacionID");                vParameters.Add("TipoIdentificacionID",tipoIdentificacionID);            }            if (!string.IsNullOrWhiteSpace(tipoIdentificacion))            {                vSql.Append(" AND TipoIdentificacion LIKE @TipoIdentificacion");                vParameters.Add("TipoIdentificacion",$"%{tipoIdentificacion}%");            }            if (bEliminado.HasValue)            {                vSql.Append(" AND bEliminado = @bEliminado");                vParameters.Add("bEliminado", bEliminado.Value);            }            var vList = await _objDbDefault.QueryAsync<dynamic>(vSql.ToString(), vParameters);            return vList;        }        public async Task<clReadTipoIdentificacion> CreateTipoIdentificacion(clCreateTipoIdentificacion objInput, int userId, string windowName)        {            string sInsertSql = $@"                --WindowName:{windowName},UserID:{userId}                INSERT INTO vts.TipoIdentificacion                (TipoIdentificacion, bEliminado, Creado, UsuarioCreacionID, FechaCreacion)                VALUES (@TipoIdentificacion, @bEliminado, @Creado, @UsuarioCreacionID, GETDATE());                SELECT CAST(SCOPE_IDENTITY() AS INT);            ";            var vInsertParams = new            {                objInput.TipoIdentificacion,                objInput.bEliminado,                Creado     = windowName,                UsuarioCreacionID = userId            };            var vNewId = await _objDbDefault.ExecuteScalarAsync<int>(sInsertSql, vInsertParams);            string sSelectSql = @"                SELECT TipoIdentificacionID, TipoIdentificacion, bEliminado                FROM vts.TipoIdentificacion (NOLOCK)                WHERE TipoIdentificacionID = @TipoIdentificacionID;";            var vReadParams = new { TipoIdentificacionID = vNewId };            var vCreated = await _objDbDefault.QuerySingleOrDefaultAsync<clReadTipoIdentificacion>(sSelectSql, vReadParams);            if (vCreated is null) throw new InvalidOperationException($"No se pudo recuperar el TipoIdentificacion con ID {vNewId}.");            return vCreated;        }        public async Task<clReadTipoIdentificacion?> UpdateTipoIdentificacion(clUpdateTipoIdentificacion objInput, int userId, string windowName)        {            var vSets = new List<string>();            var vParameters = new DynamicParameters();            vParameters.Add("TipoIdentificacionID", objInput.TipoIdentificacionID);            if (objInput.TipoIdentificacion is not null)            {                vSets.Add("TipoIdentificacion = @TipoIdentificacion");                vParameters.Add("TipoIdentificacion", objInput.TipoIdentificacion);            }            if (objInput.bEliminado != null)            {                vSets.Add("bEliminado = @bEliminado");                vParameters.Add("bEliminado", objInput.bEliminado);            }            vSets.Add($"Modificado = '{windowName}'");            vSets.Add($"UsuarioModificacionID = {userId}");            vSets.Add("FechaModificacion = GETDATE()");            var vSetClause = string.Join(", ", vSets);            var sSql = $@"                --WindowName:{windowName},UserID:{userId}                UPDATE vts.TipoIdentificacion                SET {vSetClause}                WHERE TipoIdentificacionID = @TipoIdentificacionID;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, vParameters);            if (vAffected == 0) return null;            const string sSelect = @"                SELECT TipoIdentificacionID, TipoIdentificacion, bEliminado                FROM vts.TipoIdentificacion (NOLOCK)                WHERE TipoIdentificacionID = @TipoIdentificacionID;";            return await _objDbDefault.QueryFirstOrDefaultAsync<clReadTipoIdentificacion>(sSelect, new {  objInput.TipoIdentificacionID });        }        public async Task<bool> DeleteTipoIdentificacion(int nTipoIdentificacionID)        {            const string sSql = @"                DELETE FROM vts.TipoIdentificacion                WHERE TipoIdentificacionID = @Id;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, new { Id = nTipoIdentificacionID });            return vAffected > 0;        }    }}